const DEFAULT_LOG_FREQ: f64 = -5.0;

#[inline]
fn lookup_score(hash: u64) -> f64 {
    let idx = FRAGMENT_SCORES.partition_point(|&(h, _)| h < hash);
    if idx < FRAGMENT_SCORES.len() && FRAGMENT_SCORES[idx].0 == hash {
        FRAGMENT_SCORES[idx].1 as f64 / 1000.0
    } else {
        DEFAULT_LOG_FREQ
    }
}

// ---------------------------------------------------------------------------
// Complexity corrections
// ---------------------------------------------------------------------------

fn complexity_penalty(mol: &Molecule) -> f64 {
    let n = mol.atom_count() as f64;
    if n == 0.0 {
        return 0.0;
    }

    let spiro = num_spiro_atoms(mol) as f64;
    let bridge = num_bridgehead_atoms(mol) as f64;
    let rings = ring_count(mol) as f64;
    let stereo = num_stereocenters(mol) as f64;

    let macro_count = count_macrorings(mol) as f64;

    let bond_n = mol.bond_count() as f64;
    let ring_bond_frac = if bond_n > 0.0 {
        ring_bond_count(mol) as f64 / bond_n
    } else {
        0.0
    };

    let penalty = spiro * 0.25
        + bridge * 0.35
        + macro_count * 0.30
        + stereo * 0.10
        + (rings - 1.0).max(0.0) * 0.05
        + ring_bond_frac * 0.50;

    let size_penalty = (n / 10.0 - 1.0).max(0.0) * 0.05;

    penalty + size_penalty
}

fn count_macrorings(mol: &Molecule) -> usize {
    let n = mol.atom_count();
    let rings = ring_count(mol);
    if rings == 0 {
        return 0;
    }
    let avg_ring_size = n as f64 / rings as f64;
    if avg_ring_size > 8.0 { 1 } else { 0 }
}

fn ring_bond_count(mol: &Molecule) -> usize {
    let n = mol.atom_count();
    let mut in_ring = vec![false; mol.bond_count()];
    let mut visited = vec![false; n];
    let mut bond_idx_map: HashMap<(usize, usize), usize> = HashMap::new();
    for (bidx, bond) in mol.bonds() {
        let i = bond.atom1.0 as usize;
        let j = bond.atom2.0 as usize;
        bond_idx_map.insert((i.min(j), i.max(j)), bidx.0 as usize);
    }

    let adj: Vec<Vec<usize>> = (0..n)
        .map(|i| {
            mol.neighbors(AtomIdx(i as u32))
                .map(|(nb, _)| nb.0 as usize)
                .collect()
        })
        .collect();

    let mut stack: Vec<(usize, usize, usize)> = Vec::new();
    for root in 0..n {
        if visited[root] {
            continue;
        }
        stack.push((root, usize::MAX, 0));
        while let Some((cur, par, d)) = stack.pop() {
            if visited[cur] {
                continue;
            }
            visited[cur] = true;
            let _ = d;
            for &nb in &adj[cur] {
                if nb == par {
                    continue;
                }
                if visited[nb] {
                    let key = (cur.min(nb), cur.max(nb));
                    if let Some(&bi) = bond_idx_map.get(&key) {
                        in_ring[bi] = true;
                    }
                } else {
                    stack.push((nb, cur, 0));
                }
            }
        }
    }
    in_ring.iter().filter(|&&r| r).count()
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/// Compute the Synthetic Accessibility Score for `mol`.
///
/// Returns a value in \[1, 10\]: 1 = trivially easy, 10 = very hard to synthesize.
///
/// Fragment environments use the same FNV-1a hash scheme as ECFP fingerprints
/// (`chematic_fp::morgan_fp_counts`), so the fragment table is directly
/// compatible with ECFP4 lookups.
pub fn sa_score(mol: &Molecule) -> f64 {
    let n = mol.atom_count();
    if n == 0 {
        return 10.0;
    }

    // Collect all circular environments at radii 0–2 with their occurrence counts.
    let counts = morgan_fp_counts(mol, 2);
    let total_frags: u32 = counts.values().sum();
    if total_frags == 0 {
        return 10.0;
    }

    // Fragment score = mean of log10(frequency) over all environment instances.
    // Environments not in the table use DEFAULT_LOG_FREQ (very rare).
    let total_score: f64 = counts
        .iter()
        .map(|(&hash, &count)| lookup_score(hash) * count as f64)
        .sum();
    let fscore = total_score / total_frags as f64;

    let cscore = complexity_penalty(mol);

    // Raw score: higher fscore (common fragments) → easier; higher cscore → harder.
    let raw = fscore * 2.0 - cscore * 4.5;

    // Map raw ∈ (−∞, 0] → sa ∈ [1, 10].
    let sa = 1.0 + (-raw).max(0.0);
    sa.clamp(1.0, 10.0)
}

#[cfg(test)]
mod tests {
    use super::*;
    use chematic_smiles::parse;

    fn mol(s: &str) -> Molecule {
        parse(s).unwrap()
    }

    #[test]
    fn sa_score_in_range_1_to_10() {
        for s in &["C", "CC(=O)O", "c1ccccc1", "CC(=O)Oc1ccccc1C(=O)O"] {
            let score = sa_score(&mol(s));
            assert!(
                (1.0..=10.0).contains(&score),
                "SA score for {s} = {score:.2} is out of [1, 10]"
            );
        }
    }

    #[test]
    fn simple_molecule_lower_than_complex() {
        let simple = sa_score(&mol("CC"));
        let complex = sa_score(&mol("C1CC2(CC1)CCCC2")); // spiro bicyclic
        assert!(
            simple <= complex,
            "simple {simple:.2} should be ≤ complex {complex:.2}"
        );
    }

    #[test]
    fn methane_is_easy() {
        let score = sa_score(&mol("C"));
        assert!(
            score < 6.0,
            "methane SA score should be < 6, got {score:.2}"
        );
    }

    #[test]
    fn taxol_harder_than_aspirin() {
        let aspirin = sa_score(&mol("CC(=O)Oc1ccccc1C(=O)O"));
        let taxol = sa_score(&mol(
            "CC1=C2C(C(=O)C3(C(CC4C(C3C(C(=C2OC1=O)C)(C)C)OC(=O)C5=CC=CC=C5)OC(=O)C4)O)(C)C",
        ));
        assert!(
            aspirin < taxol,
            "aspirin ({aspirin:.2}) should be easier than taxol ({taxol:.2})"
        );
    }
}
